const signed=n=>`${n>0?'+':''}${n}`;
const media=()=>`<div class="ds-media" aria-hidden="true"><video autoplay muted loop playsinline preload="metadata" poster="/assets/margin-motion-poster.jpg"><source src="/assets/margin-motion-web.mp4" type="video/mp4"></video></div>`;
const flows=()=>`<svg class="ds-flows" viewBox="0 0 1000 500" preserveAspectRatio="none" aria-hidden="true"><path d="M0 115C260 115 210 260 500 250S790 100 1000 110"/><path d="M0 250C230 250 250 330 500 250S780 340 1000 340"/><path d="M0 410C250 410 240 250 500 250S810 230 1000 230"/></svg>`;
const title=(number,label,headline,right='')=>`<div class="ds-heading"><div><p class="eyebrow"><span>${number}</span> / ${label}</p><h1>${headline}</h1></div>${right}</div>`;

export function renderWhatif(c) {
  const projected=c.margin()-c.state.shift;
  return '<section class="quiet-page"><h1>Can I take on more?</h1><p class="quiet-intro">Try a café shift that uses your available work time before Friday noon. This is only a preview; your actual week stays unchanged.</p><div class="quiet-simulation"><label for="wi-hours">Extra shift length <output id="wi-duration">'+c.state.shift+' hours</output></label><input id="wi-hours" type="range" min="1" max="3" step="1" value="'+c.state.shift+'" aria-label="Extra shift hours"><div class="wi-scale"><span>1 hour</span><span>2 hours</span><span>3 hours</span></div><section class="quiet-projection" aria-live="polite"><p>With this shift, you would be</p><div id="wi-number">'+Math.abs(projected)+'<small>hours '+(projected<0?'short':projected===0?'to spare':'free')+'</small></div><span id="wi-verdict">'+c.workHours()+'h of work would need to fit into '+(c.availableHours()-c.state.shift)+'h. '+(projected<0?'You’d need to move or share something.':'The time fits, but check how the week feels too.')+'</span></section></div><div class="quiet-approval">'+c.button('copy-reply','Copy a polite “not this time”','button primary','chat')+'<p>“I can’t take the full shift before Friday.<br>Is a weekend shift available instead?”</p></div><details class="quiet-disclosure"><summary>Want to look at your current plan instead?</summary><p>The extra shift isn’t added to your calendar. You can review suggestions for your existing commitments.</p><div class="quiet-secondary">'+c.link('rebalance','Make room in my current week','button ghost','arrow')+'</div></details><p class="quiet-footnote">Your report deadline and protected rest time stay fixed.</p></section>';
}

export function renderRebalance(c) {
  const m=c.margin(),s=c.state;
  const summary=m<0?Math.abs(m)+'h more work than time':m===0?'Everything fits, with no spare time':m+'h of room in your week';
  const status='<div class="quiet-status '+(m>=0?'good':'')+'"><div><strong>'+summary+'</strong><p>'+c.workHours()+'h of work · '+c.availableHours()+'h available before Friday, 12 PM</p></div>'+(m>=0?c.icon('check'):'')+'</div>';
  let content='';
  if(s.confirmed) {
    content='<section class="quiet-pending"><h2>Your plan is updated.</h2><ul>'+(s.moved?'<li>Groceries moved to Saturday at 11 AM.</li>':'')+'<li>Someone has agreed to take the 2h outreach task.</li><li>Your report deadline and rest time stay protected.</li></ul>'+c.link('week','See my updated week','button primary','arrow')+'</section>';
  } else if(s.requested) {
    content='<section class="quiet-pending"><h2>Help requested. Still waiting for a yes.</h2><p>'+(s.moved?'Groceries are now on Saturday. ':'')+'The 2h outreach task still counts as yours until someone agrees to take it.</p>'+c.button('confirm-handover','Try a confirmed handover','button primary','people')+'<p class="quiet-footnote">Demo step: this simulates a reply. No message is sent.</p></section>';
  } else {
    content='<div class="quiet-choices"><label class="quiet-choice"><input type="checkbox" id="move-groceries" checked '+(s.moved?'disabled':'')+'><span><strong>Move groceries to Saturday</strong><small>A flexible errand. Saturday at 11 AM instead of before Friday.</small><em>'+(s.moved?'Already moved':'Frees 1h before your deadline')+'</em></span></label><label class="quiet-choice"><input type="checkbox" id="request-help" checked><span><strong>Ask for help with committee outreach</strong><small>Share the 2h outreach task. Keep your own 1h of preparation.</small><em>Only frees time once someone agrees.</em></span></label></div><div class="quiet-approval">'+c.button('apply-plan','Apply selected suggestions','button primary','arrow')+'<p>You choose what changes.<br>Nothing is sent outside this demo.</p></div>';
  }
  return '<section class="quiet-page"><h1>Make a little room.</h1><p class="quiet-intro">'+(s.confirmed?'A lighter plan, with the important things still in place.':s.requested?'One change at a time. Here’s where your plan stands.':'Start with these two suggestions. Your deadlines and rest stay protected.')+'</p>'+status+content+(s.requested&&!s.moved?'<div class="quiet-secondary">'+c.button('move-groceries-only','Move groceries to Saturday · free 1h','text-button','calendar')+'</div>':'')+(c.hasUndo?'<div class="quiet-secondary">'+c.button('undo','Undo last change','text-button','reset')+'</div>':'')+'<details class="quiet-disclosure"><summary>How is this worked out?</summary><p>The original week has 6h of report work, 3h of committee work and 1h for groceries. Only 8h of compatible work time remain before Friday noon, after classes, shifts, travel and rest. Moving groceries frees 1h. An agreed handover removes another 2h.</p><p>A pending request doesn’t reduce your workload. Completed work reduces both the work remaining and its reserved time.</p></details></section>';
}

export function renderRecovery(c){return `<section class="personal-calm recovery-calm"><header class="calm-heading"><h1>Take a break</h1><p>A minute to yourself, if you want one.</p></header><div class="rc-breath calm-timer" aria-label="Optional one-minute timer"><output id="rc-time" aria-live="off">1:00</output><p id="rc-status" role="status">Whenever you’re ready.</p><div class="calm-timer-controls"><button class="button primary" id="rc-start" type="button">Start timer</button><button class="button ghost" id="rc-reset" type="button" disabled>Reset</button></div></div><details class="calm-details"><summary>Other ways to pause</summary><div class="calm-suggestions"><button type="button" data-action="recovery-walk">${c.icon('leaf')}Take a short walk</button><button type="button" data-action="recovery-friend">${c.icon('people')}Check in with a friend</button><button type="button" data-action="recovery-quiet">${c.icon('moon')}Keep some quiet time</button></div></details>${c.link('week','Back to your week','calm-back','arrow')}</section>`}

export function renderSettings(c){const s=c.state.settings;return `<section class="personal-calm preferences-calm"><form id="settings-form"><header class="calm-heading calm-form-heading"><h1>Your preferences</h1><button class="button primary" type="submit">Save</button></header><div class="calm-fields"><label class="calm-field"><span>Focus starts</span><input type="time" name="focus" value="${s.focus}" required></label><label class="calm-field"><span>Wind-down begins</span><input type="time" name="rest" value="${s.rest}" required></label><label class="calm-field"><span>Focus session</span><select name="session">${[['60','60 minutes'],['90','90 minutes'],['120','2 hours']].map(([v,l])=>`<option value="${v}" ${s.session===v?'selected':''}>${l}</option>`).join('')}</select></label></div><details class="calm-details"><summary>Optional weekly check-in</summary><div class="calm-checkin">${[['mental','Mental effort'],['physical','Physical effort'],['social','Social effort'],['admin','Life admin']].map(([name,label])=>`<label class="calm-field"><span>${label}</span><select name="${name}">${['Light','Moderate','High'].map(l=>`<option ${s[name]===l?'selected':''}>${l}</option>`).join('')}</select></label>`).join('')}<p class="calm-note">Your own estimates, not a health score.</p></div></details><p class="calm-note">Saved for this demo session. The sample calendar’s work windows stay fixed.</p></form></section>`}

export function mountDecisionScenes(c){const cleanups=[];const slider=document.querySelector('#wi-hours');if(slider)slider.addEventListener('input',()=>{c.state.shift=Number(slider.value);const projected=c.margin()-c.state.shift;document.querySelector('#wi-duration').textContent=c.state.shift+' '+(c.state.shift===1?'hour':'hours');document.querySelector('#wi-number').innerHTML=Math.abs(projected)+'<small>hours '+(projected<0?'short':projected===0?'to spare':'free')+'</small>';document.querySelector('#wi-verdict').textContent=c.workHours()+'h of work would need to fit into '+(c.availableHours()-c.state.shift)+'h. '+(projected<0?'You’d need to move or share something.':'The time fits, but check how the week feels too.');});
const start=document.querySelector('#rc-start');if(start){let remaining=60,deadline=0,interval;const reset=document.querySelector('#rc-reset');const clear=()=>{clearInterval(interval);interval=null};const update=()=>{remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));document.querySelector('#rc-time').textContent=`${Math.floor(remaining/60)}:${String(remaining%60).padStart(2,'0')}`;if(remaining===0){clear();start.textContent='Another minute';document.querySelector('#rc-status').textContent='That minute was yours.';document.querySelector('.rc-breath')?.classList.remove('active')}};start.addEventListener('click',()=>{if(interval){clear();start.textContent='Continue the pause';document.querySelector('#rc-status').textContent='Paused. There’s no hurry.';document.querySelector('.rc-breath').classList.remove('active')}else{if(remaining===0)remaining=60;deadline=Date.now()+remaining*1000;interval=setInterval(update,250);start.textContent='Pause timer';reset.disabled=false;document.querySelector('#rc-status').textContent='Nothing you need to do.';document.querySelector('.rc-breath').classList.add('active')}});reset.addEventListener('click',()=>{clear();remaining=60;document.querySelector('#rc-time').textContent='1:00';document.querySelector('#rc-status').textContent='Whenever you’re ready.';start.textContent='Take a minute';reset.disabled=true;document.querySelector('.rc-breath').classList.remove('active')});window.addEventListener('hashchange',clear,{once:true});cleanups.push(()=>{clear();window.removeEventListener('hashchange',clear)});}
document.querySelector('.ps-world input[name="focus"]')?.addEventListener('input',e=>{document.querySelector('#ps-focus-preview').textContent=e.target.value;document.querySelector('.ps-dial-hand').style.setProperty('--angle',`${Number(e.target.value.split(':')[0])/24*360}deg`)});document.querySelectorAll('.ps-level select').forEach(select=>select.addEventListener('change',()=>{select.closest('.ps-level').querySelectorAll('i').forEach((bar,i)=>bar.classList.toggle('lit',i<{Light:3,Moderate:7,High:11}[select.value]))}));return ()=>cleanups.forEach(fn=>fn());}
